INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u1-pronouns', '人称代词和物主代词', 'A1', 7, '人称代词:作主语用主格(I/we/he…),作宾语或表语用宾格(me/us/him…);单独作答或带 not 的简短回答常用宾格(—Who is it? —Me.);it 可表时间/天气/距离。物主代词:形容词性(my/our/your/his/her/its/their)用在名词前;名词性(mine/ours/yours/his/hers/its/theirs)独立使用,代替“形容词性+名词”。', 2, 'wy7A', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-starter-basics', '综合基础(be动词·指示代词·冠词·名词复数)', 'A1', 7, 'be 动词随主语变化:I 用 am,单数用 is,复数或 you 用 are。指示代词:近指单数 this、复数 these,远指单数 that、复数 those。不定冠词:辅音音素前用 a,元音音素前用 an。名词复数:一般加 -s,以 s/x/ch/sh 结尾加 -es。There be 表存在:单数用 There is,复数用 There are。', 1, 'wy7A', 'Starter', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u2-simple-present', '一般现在时', 'A1', 7, '一般现在时表习惯或事实。主语为第三人称单数时,动词加 -s/-es(watch→watches, go→goes, study→studies, have→has);其余主语用动词原形。否定与疑问借助助动词 do/does:三单用 does/doesn''t,其余用 do/don''t,助动词后动词一律用原形。常与 every day、on Sundays 等状语连用。', 3, 'wy7A', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u3-possessive-nouns', '名词所有格', 'A1', 7, '表示“……的”:单数名词及不以 s 结尾的名词加 ''s(Tom''s, children''s);以 s 结尾的复数名词只加撇号 ''(students'', boys'')。无生命的事物多用 of 结构(the door of the room)。两人共有一物,只在最后一个名词后加 ''s(Lucy and Lily''s room);各有其物,则各自加 ''s(Tom''s and Sam''s bags)。', 4, 'wy7A', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u4-adverbs-of-frequency', '频度副词', 'A1', 7, '频度副词表示动作发生的频繁程度:always(总是)、usually(通常)、often(经常)、sometimes(有时)、never(从不)。位置:放在实义动词之前(He often plays.),但放在 be 动词之后(He is never late.)。提问频率用 how often。never 本身表否定,不再与 not 连用。表频率的短语(every day, twice a week)通常放在句末。', 5, 'wy7A', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='other' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u5-simple-future', '一般将来时', 'A1', 7, '一般将来时表示将要发生的动作,常与 tomorrow、next week、soon 连用。两种结构:will + 动词原形;be(am/is/are) going to + 动词原形。否定:will not = won''t;be not going to。一般疑问把 will 或 be 提到句首。There will be… 表示“将会有”。', 6, 'wy7A', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (publisher, code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('junior_fltrp', 'wy7-u6-present-continuous', '现在进行时', 'A1', 7, '现在进行时表示此刻正在进行的动作,结构为 be(am/is/are)+ 动词的 -ing 形式,常与 now、Look!、Listen! 连用。现在分词拼写:一般直接加 -ing(read→reading);以不发音 e 结尾去 e 加 -ing(write→writing);重读闭音节双写末尾辅音字母(swim→swimming, sit→sitting)。否定在 be 后加 not;疑问把 be 提到句首。', 7, 'wy7A', 'U6', (SELECT id FROM public.junior_grammar_categories WHERE code='tense' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), '____ am a middle school student now.', 'Me', 'Mine', 'My', 'I', 'D', '作主语用主格 I。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'My grandpa often tells ____ good stories.', 'me', 'I', 'mine', 'my', 'A', '作宾语用宾格 me。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), '____ school uniform is blue and white.', 'Me', 'I', 'My', 'Mine', 'C', '名词 uniform 前用形容词性物主代词 my。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Tom is my classmate. ____ is good at maths.', 'Him', 'He', 'His', 'He''s', 'B', '作主语用主格 He；He''s=He is。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Our teacher helps ____ with English every day.', 'us', 'our', 'we', 'ours', 'A', '作宾语用宾格 us。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'The students are cleaning ____ classroom now.', 'theirs', 'their', 'they', 'them', 'B', '名词 classroom 前用形容词性物主代词 their。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Lily loves ____ new bike very much.', 'she''s', 'hers', 'her', 'she', 'C', '名词 bike 前用形容词性物主代词 her。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'We all love ____ school.', 'us', 'ours', 'we', 'our', 'D', '名词 school 前用形容词性物主代词 our。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Welcome to our school! Nice to meet ____!', 'you', 'you''re', 'yours', 'your', 'A', 'meet 后作宾语用宾格 you。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'This blue pen isn''t yours. It''s ____.', 'my', 'mine', 'me', 'I', 'B', '名词性物主代词 mine 代替 my pen。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), '____ is sunny and warm today.', 'He', 'That', 'This', 'It', 'D', 'it 可表天气。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), '— Is this schoolbag ____? — Yes, it''s mine.', 'your', 'you''re', 'yours', 'you', 'C', '名词性物主代词 yours 代替 your schoolbag。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), '— Who is at the door? — ____.', 'Mine', 'My', 'I', 'Me', 'D', '单独作答常用宾格 Me；主格一般不单独使用。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'This is our school library. ____ reading room is very big.', 'It''s', 'Its', 'It', 'Their', 'B', 'its 修饰名词 reading room 表“它的”；It''s=It is；library 单数不用 Their。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'These red shoes are ____, not mine.', 'her''s', 'she', 'hers', 'her', 'C', '名词性物主代词 hers 代替 her shoes；无 her''s 写法。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Peter has an eraser. This one is ____.', 'his', 'her', 'he', 'him', 'A', '名词性物主代词 his 代替 his eraser。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'My sister and I share a room. The bed near the window is ____.', 'my', 'I', 'mine', 'me', 'C', '名词性物主代词 mine 代替 my bed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Lily can''t find her ruler. Can you give ____ mine? ____ needs it now.', 'she; Her', 'her; She', 'her; Her', 'hers; She', 'B', 'give 后接宾格 her（间接宾语）；第二空作主语用主格 She。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'Anna has a red schoolbag and I have a blue one. The red one is ____, and the blue one is ____.', 'her; mine', 'her; my', 'hers; my', 'hers; mine', 'D', '独立使用代替 Anna''s bag / my bag，用名词性物主代词 hers 和 mine。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u1-pronouns'), 'My parents work hard. I love ____, and ____ love me too.', 'them; they', 'they; them', 'their; they', 'them; their', 'A', 'love 后接宾格 them；第二空作主语用主格 they。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'I ____ a middle school student.', 'be', 'are', 'is', 'am', 'D', '主语 I 用 be 动词 am。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'This ____ my English teacher.', 'is', 'are', 'be', 'am', 'A', '单数主语用 is。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'My parents ____ teachers.', 'is', 'are', 'be', 'am', 'B', '复数主语用 are。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'You ____ my good friend.', 'is', 'be', 'are', 'am', 'C', '主语 you 用 are。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ is my new schoolbag.', 'They', 'This', 'These', 'Those', 'B', '近指单数用 this。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ are my classmates.', 'That', 'This', 'These', 'It', 'C', '近指复数用 these。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'Look at ____ bird in the tree over there.', 'these', 'this', 'those', 'that', 'D', '远处的单只鸟,远指单数用 that。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'This is ____ apple.', 'an', 'a', 'and', 'am', 'A', '元音音素开头的 apple 前用 an。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'I have ____ new bike.', 'and', 'am', 'an', 'a', 'D', '辅音音素开头的 new 前用 a。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'There are three ____ on the desk.', 'a book', 'bookes', 'books', 'book', 'C', '可数名词复数一般加 -s。', 1, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'I can see two ____ in the room.', 'boxes', 'boxies', 'box', 'boxs', 'A', '以 x 结尾的名词复数加 -es。', 1, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ some students in the classroom.', 'There is', 'There are', 'They are', 'It is', 'B', '复数 students 用 There are 表存在。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ those your books on the floor? Yes, ____ are.', 'Are; it', 'Is; they', 'Are; they', 'Am; they', 'C', '复数主语 those 用 are;简答用复数代词 they。', 3, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'This is not a pen. It''s ____ eraser.', 'two', 'the one', 'a', 'an', 'D', '元音音素开头的 eraser 前用 an。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'My father and mother ____ doctors.', 'is', 'are', 'be', 'am', 'B', 'and 连接的复数主语用 are。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'There are many ____ in my school.', 'buses', 'bus', 'buss', 'busies', 'A', '以 s 结尾的名词复数加 -es。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ a big tree near my school.', 'It is', 'There are', 'There is', 'They are', 'C', '单数 a big tree 用 There is 表存在。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'Kate and I ____ in the same class.', 'are', 'is', 'am', 'be', 'A', 'Kate and I 是复数,用 are。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), 'This is ____ egg and ____ old box, not ____ new bag.', 'a; an; a', 'an; an; a', 'a; a; a', 'an; a; a', 'B', 'egg、old 以元音音素开头用 an;new 以辅音音素开头用 a。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-starter-basics'), '____ that boy your brother? No, ____ isn''t.', 'Is; it', 'Is; she', 'Are; he', 'Is; he', 'D', '单数主语 that boy 用 is;指男孩用主格 he。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'He ____ football every day.', 'playing', 'to play', 'play', 'plays', 'D', '第三人称单数,动词加 -s。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'She ____ TV after dinner.', 'watches', 'watch', 'watching', 'watchs', 'A', 'watch 以 ch 结尾,三单加 -es。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'My father ____ to work by bus.', 'gos', 'goes', 'go', 'going', 'B', 'go 三单加 -es。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'Lucy ____ a nice bike.', 'have', 'haves', 'has', 'having', 'C', 'have 的三单形式是 has。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'They ____ English at school.', 'study', 'studys', 'studying', 'studies', 'A', '复数主语用动词原形。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'I ____ up at six every morning.', 'gets', 'got', 'get', 'getting', 'C', '主语 I 用动词原形。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'We ____ our classroom every day.', 'cleaning', 'clean', 'cleans', 'to clean', 'B', '复数主语用动词原形。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'Tom ____ his homework in the evening.', 'do', 'dos', 'doing', 'does', 'D', 'do 的三单形式是 does。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'The girl ____ her hands before lunch.', 'wash', 'washs', 'washes', 'washing', 'C', 'wash 以 sh 结尾,三单加 -es。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), '____ your sister like music?', 'Is', 'Are', 'Do', 'Does', 'D', '三单一般疑问用 Does + 动词原形。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), '____ they go to school on Sundays?', 'Do', 'Are', 'Does', 'Is', 'A', '复数主语一般疑问用 Do。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'My brother doesn''t ____ milk in the morning.', 'drank', 'drink', 'drinks', 'drinking', 'B', 'doesn''t 后接动词原形。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), '— Does Anna live near here? — Yes, she ____.', 'lives', 'do', 'is', 'does', 'D', '三单一般疑问的肯定简答用 does。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'Mike and I ____ swimming after school.', 'goes', 'to go', 'go', 'going', 'C', '并列主语为复数,用原形 go。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'She ____ have breakfast at home.', 'isn''t', 'doesn''t', 'not', 'don''t', 'B', '三单否定用 doesn''t + 原形。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'My friend ____ like sports at all.', 'doesn''t', 'not', 'isn''t', 'don''t', 'A', '三单主语否定用 doesn''t。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'Lily ____ her grandma every weekend.', 'visiting', 'visit', 'visits', 'visites', 'C', '三单动词加 -s。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'My friend Ben ____ like fish, but he ____ chicken very much.', 'doesn''t; likes', 'isn''t; likes', 'don''t; like', 'doesn''t; like', 'A', '三单否定 doesn''t + 原形;肯定谓语 likes 加 -s。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), 'Anna ____ in a small town. Every day she ____ to school and ____ her friends there.', 'lives; go; meets', 'live; go; meet', 'lives; goes; meet', 'lives; goes; meets', 'D', '三单主语,三个谓语都加 -s/-es。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u2-simple-present'), '— How often ____ Tom read books? — He ____ books every evening.', 'does; read', 'does; reads', 'is; reads', 'do; reads', 'B', '疑问句用助动词 does + 原形;陈述句谓语 reads 加 -s。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'This is ____ bag. It''s not mine.', 'Lilys', 'Lilys''', 'Lily''s', 'Lily', 'C', '单数名词表所属加 ''s。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), '____ pencil is on the desk.', 'Tom''s', 'Toms''', 'Toms', 'Tom', 'A', '单数名词加 ''s。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'I have only one sister. That is my ____ room.', 'sister', 'sister''s', 'sisters', 'sisters''', 'B', '只有一个姐姐,单数名词加 ''s。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'There are many students in our class. These are the ____ books, not the teachers''.', 'student''s', 'studentss', 'students', 'students''', 'D', '许多学生,以 s 结尾的复数名词只加撇号。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The ____ toys are new.', 'childrens', 'children', 'children''s', 'childrens''', 'C', '不规则复数 children 加 ''s。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'I have two brothers. These are my ____ bikes.', 'brothers', 'brothers''', 'brother''s', 'brotherss', 'B', '两个哥哥,复数名词只加撇号。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'Our class has only one teacher. Where is the ____ office?', 'teacher''s', 'teacher', 'teachers', 'teachers''', 'A', '只有一位老师,单数名词加 ''s。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The ____ room is over there.', 'womens', 'women', 'womens''', 'women''s', 'D', '不规则复数 women 加 ''s。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'Is this ____ ruler?', 'Jacks', 'Jacks''', 'Jack''s', 'Jack', 'C', '单数名词 Jack 加 ''s。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The door ____ the room is red.', 'for', 'of', '''s', 'in', 'B', '无生命名词多用 of 结构表所属。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'There are five boys in this room. These are the ____ desks.', 'boyss', 'boys', 'boy''s', 'boys''', 'D', '五个男孩,复数名词只加撇号。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'Do you like ____ new dress?', 'Anna''s', 'Anna', 'Annas''', 'Annas', 'A', '单数名词 Anna 加 ''s。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The colour ____ the car is black.', '''s', 'of', 'at', 'on', 'B', '无生命名词用 of 结构。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The three girls are my friends. The ____ bags are on the floor.', 'girl''s', 'girls', 'girlss', 'girls''', 'D', '三个女孩,复数名词只加撇号。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'The legs ____ the table are short.', 'of', 'off', '''s', 'for', 'A', '无生命名词 table 用 of 结构。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'That is ____ office.', 'Mr Green', 'Mr Greens', 'Mr Green''s', 'Mr Greens''', 'C', '单数名词 Mr Green 加 ''s。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'My two ____ books are on the desk.', 'friend''s', 'friends''', 'friends', 'friendss', 'B', '复数名词 friends 只加撇号表所属。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'Lucy and Lily are sisters. They share one bedroom. ____ bedroom is very big.', 'Lucy and Lily''s', 'Lucy''s and Lily', 'Lucy''s and Lily''s', 'Lucy and Lily', 'A', '共有一间卧室,只在最后一个名词后加 ''s。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'Tom and Sam each have a schoolbag. ____ schoolbags are both red.', 'Tom and Sam''s', 'Tom''s and Sam', 'Toms and Sams', 'Tom''s and Sam''s', 'D', '各有其物,两个名词都加 ''s。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u3-possessive-nouns'), 'We have one teacher and many students. Is this ____ dictionary or ____?', 'the teachers''; the student''s', 'the teachers; the student''s', 'the teacher''s; the students''', 'the teacher''s; the students', 'C', '一位老师(单数加 ''s)、许多学生(复数只加撇号)。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Ann ____ walks to school. She does it every day.', 'usually', 'never', 'sometimes', 'always', 'D', '“每天都”表示频率最高,用 always。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Ben ____ drinks coffee. He doesn''t drink it at all.', 'never', 'often', 'always', 'usually', 'A', '“一点也不喝”表示从不,用 never。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'We ____ go swimming, only now and then.', 'always', 'never', 'sometimes', 'usually', 'C', '“偶尔”用 sometimes。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'My father ____ gets home at six; he does so almost every day.', 'often', 'usually', 'sometimes', 'never', 'B', '“几乎每天”用 usually。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Lily ____ reads English books; she reads them many times a week.', 'always', 'never', 'often', 'sometimes', 'C', '“一周很多次”用 often。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Kate ____ goes to bed at nine; she does so almost every night.', 'sometimes', 'usually', 'never', 'always', 'B', '“几乎每晚”用 usually。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'My mother ____ cooks nice food. We enjoy it every day.', 'always', 'often', 'sometimes', 'never', 'A', '“每天都”用 always。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'He ____ plays computer games, maybe once a month.', 'usually', 'often', 'always', 'sometimes', 'D', '“大约一个月一次”用 sometimes。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Tom is a good student. He is ____ late for class; he always comes on time.', 'always', 'never', 'often', 'usually', 'B', '“总是准时”即从不迟到,be 动词后用 never。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), '— ____ do you play sports? — Twice a week.', 'How often', 'How many', 'How long', 'How much', 'A', '提问频率用 how often。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'My English teacher is ____ kind to us; she helps everyone every day.', 'never', 'often', 'sometimes', 'always', 'D', 'be 动词后接频度副词;“每天都帮”用 always。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'They ____ help others; they do good things many times a week.', 'always', 'sometimes', 'often', 'never', 'C', '实义动词前接频度副词;“一周很多次”用 often。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'My uncle works far away. He is ____ at home from Monday to Friday.', 'usually', 'never', 'always', 'often', 'B', '离家远,周一到五几乎不在家,be 动词后用 never。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), '— How often does your sister go swimming? — She goes ____.', 'at home', 'by bus', 'twice a week', 'very well', 'C', 'how often 提问频率,答句用频率短语 twice a week。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'My grandma ____ watches TV in the evening; she watches it many times a week.', 'often', 'always', 'sometimes', 'never', 'A', '实义动词前接频度副词;“很多次”用 often。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'We have an English lesson ____.', 'always', 'very', 'never', 'every day', 'D', '表频率的短语 every day 放在句末。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'I visit my uncle ____.', 'never week', 'always day', 'twice a week', 'often a', 'C', '表频率短语 twice a week 放句末。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), '— Does Lily ever eat fast food? — No, she ____ eats it.', 'not ever', 'never', 'doesn''t never', 'never not', 'B', 'never 本身表否定,不再加 doesn''t。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), '— How often does Ben go to the library? — He ____ goes there, about three times a week.', 'often', 'often is', 'is often', 'never', 'A', 'often 放实义动词 goes 之前;一周三次频率高,不用 never。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u4-adverbs-of-frequency'), 'Mr Li is a busy doctor. He is ____ free from Monday to Friday, but he ____ takes us to the park on Sundays.', 'always; sometimes', 'never; never', 'sometimes; never', 'never; sometimes', 'D', '周一到周五忙,be 动词后用 never;周日“有时”带我们去,实义动词前用 sometimes。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'I ____ visit my grandma tomorrow.', 'am', 'was', 'do', 'will', 'D', 'will + 动词原形表将来。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'She will ____ us next week.', 'helps', 'helping', 'help', 'helped', 'C', 'will 后接动词原形。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'They ____ going to have a party.', 'are', 'do', 'will', 'is', 'A', 'be going to 结构中主语为复数用 are。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'It ____ rain this afternoon.', 'was', 'will', 'does', 'is', 'B', 'will 表将来,后接原形 rain。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'We are going to ____ a film tonight.', 'watches', 'watching', 'watched', 'watch', 'D', 'be going to 后接动词原形。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'He ____ be twelve next year.', 'is', 'does', 'will', 'was', 'C', 'next year 表将来,用 will be。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'There ____ be a sports meeting tomorrow.', 'will', 'is', 'does', 'are', 'A', 'There will be 表“将会有”。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'My friends ____ going to visit Beijing.', 'be', 'are', 'is', 'will', 'B', 'be going to 中复数主语用 are。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'You ____ see him soon.', 'were', 'do', 'are', 'will', 'D', 'soon 表将来,用 will。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), '____ you help me with my English?', 'Will', 'Are', 'Do', 'Is', 'A', 'will 的一般疑问把 will 提前。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'He ____ come to the party because he is ill.', 'doesn''t', 'won''t', 'wasn''t', 'isn''t', 'B', 'won''t = will not,表将来否定。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), '— Will it be sunny tomorrow? — Yes, it ____.', 'is', 'does', 'will', 'be', 'C', 'will 疑问的肯定简答用 will。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), '____ she going to buy a new bag?', 'Will', 'Does', 'Are', 'Is', 'D', 'be going to 的疑问用 be,单数用 Is。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'We ____ not going to stay at home this weekend.', 'are', 'is', 'will', 'do', 'A', 'be going to 否定在 be 后加 not。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), '— Will they arrive soon? — No, they ____.', 'willn''t', 'won''t', 'aren''t', 'don''t', 'B', 'will 疑问的否定简答用 won''t;无 willn''t。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'There ____ be any classes next Sunday.', 'aren''t', 'isn''t', 'won''t', 'doesn''t', 'C', 'There will be 的否定用 won''t be。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'What ____ you do this weekend?', 'is', 'are', 'do', 'will', 'D', '询问将来计划用 will。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'My sister ____ go to school tomorrow because she ____ visit the doctor.', 'won''t; will', 'isn''t; will', 'willn''t; will', 'won''t; wills', 'A', '将来否定 won''t + 原形;肯定 will + 原形。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), '— What are you going to do next Sunday? — I ____ going to ____ my uncle.', 'am; visiting', 'am; visit', 'am; visits', 'will; visit', 'B', 'be going to 中主语 I 用 am,后接原形 visit。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u5-simple-future'), 'Look at the clouds. It ____ rain soon, so I ____ take an umbrella.', 'will; am', 'is; will', 'will; will', 'won''t; will', 'C', '两处都表将来,用 will + 原形。', 3, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Look! The children ____ playing football.', 'do', 'am', 'are', 'is', 'C', '复数主语 children 用 are。', 1, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'She ____ reading a book now.', 'am', 'do', 'are', 'is', 'D', '单数主语用 is。', 1, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'I ____ doing my homework.', 'am', 'do', 'are', 'is', 'A', '主语 I 用 am。', 1, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Listen! Someone ____ singing.', 'does', 'is', 'am', 'are', 'B', 'someone 视为单数,用 is。', 1, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'They ____ swimming in the pool.', 'are', 'be', 'am', 'is', 'A', '复数主语用 are。', 1, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'He is ____ a picture now.', 'draw', 'drawing', 'drew', 'draws', 'B', '现在进行时用动词 -ing 形式。', 1, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Look, the dog ____ running fast.', 'are', 'be', 'is', 'am', 'C', '单数主语 the dog 用 is。', 1, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'We ____ cleaning the classroom.', 'is', 'am', 'do', 'are', 'D', '复数主语 we 用 are。', 1, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'My mother is ____ dinner in the kitchen.', 'cooked', 'cooking', 'cook', 'cooks', 'B', '现在进行时用 cooking。', 1, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'The boys are ____ in the river.', 'swiming', 'swimmming', 'swims', 'swimming', 'D', 'swim 重读闭音节,双写 m 加 -ing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Tom is ____ a letter to his friend.', 'writing', 'writting', 'writeing', 'writes', 'A', 'write 去掉不发音的 e 加 -ing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Look! She is ____ a kite in the park.', 'fling', 'flys', 'flying', 'flieing', 'C', 'fly 直接加 -ing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'The cat is ____ on the chair.', 'siting', 'sitting', 'sits', 'sittting', 'B', 'sit 重读闭音节,双写 t 加 -ing。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'He ____ watching TV; he is reading a book.', 'aren''t', 'doesn''t', 'isn''t', 'not', 'C', '现在进行时否定在 be 后加 not。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), '____ you listening to me now?', 'Is', 'Do', 'Be', 'Are', 'D', '现在进行时疑问把 be 提前,主语 you 用 Are。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'What ____ they doing now?', 'are', 'do', 'be', 'is', 'A', '复数主语 they 的进行时疑问用 are。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'The students are ____ an English song.', 'sings', 'singeing', 'singging', 'singing', 'D', 'sing 直接加 -ing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), '— What ____ your father ____ now? — He ____ washing the car.', 'is; doing; is', 'does; doing; is', 'is; doing; does', 'is; do; is', 'A', '进行时疑问 is + doing;简答 is washing。', 3, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Usually I ____ to school by bike, but look, today I ____ the bus.', 'go; take', 'go; am taking', 'am going; am taking', 'am going; take', 'B', 'usually 用一般现在时 go;look/today 表此刻,用进行时 am taking。', 3, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='junior_fltrp' AND volume='wy7A' AND code='wy7-u6-present-continuous'), 'Listen! The girls ____ dancing and the boy ____ singing.', 'are; are', 'is; is', 'are; is', 'is; are', 'C', '复数 girls 用 are,单数 boy 用 is。', 3, 20, 'mcq');
